            );
        }
        let long = "a".repeat(256);
        for (query, candidate) in [(long.clone(), "aaa".into()), ("aaa".into(), long)] {
            sqlx::query!("DELETE FROM exposed.funders")
                .execute(&pool)
                .await?;
